 private void waitFor(java.util.concurrent.Callable<Boolean> test,long timeout,String label)throws Exception{long until=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<until){if(test.call())return;Thread.sleep(100);}throw new AssertionError(label+" status="+(engine==null?0:engine.status));}
