 private byte[] imageBytes(int color)throws Exception {Bitmap image=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);image.eraseColor(color);ByteArrayOutputStream out=new ByteArrayOutputStream();require(image.compress(Bitmap.CompressFormat.PNG,100,out),"synthetic PNG created");image.recycle();return out.toByteArray();}
 private boolean mediaExists(Uri uri)throws Exception {try(android.database.Cursor c=target.getContentResolver().query(uri,new String[]{android.provider.MediaStore.MediaColumns._ID},null,null,null)){return c!=null&&c.moveToFirst();}}
 private String mediaKey(ProtocolCore.Item item){return ProtocolCore.hex(item.hash)+":"+item.size+":"+item.mime;}
 private ProtocolCore.Item mediaSource(byte[] bytes,Uri directory)throws Exception {Uri parent=DocumentsContract.buildDocumentUriUsingTree(tree(),"root");Uri file=DocumentsContract.createDocument(target.getContentResolver(),parent,"image/png","synthetic-photo.png");try(OutputStream out=target.getContentResolver().openOutputStream(file,"w")){out.write(bytes);}ProtocolCore.Item item=new ProtocolCore.Item(ProtocolCore.token(16),"synthetic-photo.png","image/png",bytes.length,ProtocolCore.sha256(bytes));engine.store.received(ProtocolCore.token(16),item,file,directory);return item;}
 private void gallery(Bundle result)throws Exception {
  phase="gallery-create";Uri directory=tree().buildUpon().appendQueryParameter("synthetic-run",ProtocolCore.token(16)).build();runOnMainSync(()->engine.setDirectory(tree()));byte[] bytes=imageBytes(0xff000000|new java.util.Random().nextInt(0xffffff));ProtocolCore.Item one=mediaSource(bytes,directory);CancellationScope scope=new CancellationScope(Runnable::run,()->{});
  MediaImporter.Result first=new MediaImporter(target,scope).run(engine.store,directory,(n,k,f)->{});require(first.imported==1&&first.failed==0,"actual MediaStore image import");MediaImportStore journal=new MediaImportStore(target);Uri dest=journal.get(mediaKey(one)).dest;require(mediaExists(dest),"gallery row visible");try(android.database.Cursor c=target.getContentResolver().query(dest,new String[]{android.provider.MediaStore.MediaColumns.IS_PENDING},null,null,null)){require(c!=null&&c.moveToFirst()&&c.getInt(0)==0,"pending cleared only after verification");}
  MediaImporter.Result repeat=new MediaImporter(target,scope).run(engine.store,directory,(n,k,f)->{});require(repeat.imported==0&&repeat.skipped==1&&repeat.failed==0,"retry no duplicate copy");require(dest.equals(journal.get(mediaKey(one)).dest),"same gallery URI after retry");
  // A journal may still say pending after publication. Editing this public copy must never cause deletion.
  journal.put(mediaKey(one),dest,"pending");try(OutputStream out=target.getContentResolver().openOutputStream(dest,"w")){out.write(new byte[]{9,8,7});}
  MediaImporter.Result edited=new MediaImporter(target,scope).run(engine.store,directory,(n,k,f)->{});require(edited.failed==1&&edited.imported==0,"changed visible copy reports failure");require(mediaExists(dest),"changed public copy retained");
  phase="gallery-intent-recovery";byte[] next=imageBytes(0xff000000|new java.util.Random().nextInt(0xffffff));ProtocolCore.Item two=mediaSource(next,directory);String name="CT-"+ProtocolCore.token(16)+"-synthetic-recovery.png";journal.intent(mediaKey(two),name);android.content.ContentValues values=new android.content.ContentValues();values.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,name);values.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,"image/png");values.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,"Pictures/ChinaTech/");values.put(android.provider.MediaStore.MediaColumns.IS_PENDING,1);Uri interrupted=target.getContentResolver().insert(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);require(interrupted!=null,"fixture created between insert and URI journal");try(OutputStream out=target.getContentResolver().openOutputStream(interrupted,"w")){out.write(next);}
  MediaImporter.Result recovered=new MediaImporter(target,scope).run(engine.store,directory,(n,k,f)->{});result.putString("recoveryResult",recovered.imported+"/"+recovered.skipped+"/"+recovered.failed+" "+recovered.lastFailure);require(recovered.imported==0&&recovered.skipped==1&&recovered.failed==1,"creation intent recovered without another copy");require(interrupted.equals(journal.get(mediaKey(two)).dest),"creation intent resolves exact URI");require("published".equals(journal.get(mediaKey(two)).state),"recovered row committed");
  // Journal lives independently of the scan index and a newly constructed importer.
  journal.close();MediaImportStore reopened=new MediaImportStore(target);require(reopened.get(mediaKey(two)).dest.equals(interrupted),"journal persists across helper recreation");reopened.close();result.putBoolean("actualMediaStoreImportAndRecovery",true);result.putInt("galleryChecks",checks);phase="complete";
 }
 private void tls(Bundle result)throws Exception {SessionTls id=new SessionTls(System.currentTimeMillis()+600000);try(javax.net.ssl.SSLServerSocket server=(javax.net.ssl.SSLServerSocket)id.context.getServerSocketFactory().createServerSocket(0,1,InetAddress.getLoopbackAddress())){server.setSoTimeout(10000);java.util.concurrent.CompletableFuture<Boolean> remote=new java.util.concurrent.CompletableFuture<>();new Thread(()->{try(javax.net.ssl.SSLSocket peer=(javax.net.ssl.SSLSocket)server.accept()){peer.setSoTimeout(10000);peer.startHandshake();peer.getOutputStream().write(42);peer.getOutputStream().flush();remote.complete(true);}catch(Throwable e){result.putString("serverFailure",e.getClass().getSimpleName());remote.completeExceptionally(e);}}).start();try(javax.net.ssl.SSLSocket socket=(javax.net.ssl.SSLSocket)SessionTls.pinned(id.pin).getSocketFactory().createSocket(InetAddress.getLoopbackAddress(),server.getLocalPort())){socket.setSoTimeout(10000);socket.startHandshake();require(socket.getInputStream().read()==42,"actual AndroidKeyStore TLS pinned handshake");require(remote.get(10,java.util.concurrent.TimeUnit.SECONDS),"server handshake");result.putBoolean("pinnedAndroidTls",true);}catch(Exception clientError){try{remote.get(10,java.util.concurrent.TimeUnit.SECONDS);}catch(Exception ignored){}throw clientError;}}finally{id.close();}}
