  long total=0;for(long after=0;;){TransferStore.MediaReceipt row=RestoreCatalog.next(engine.store,runDirectory,after);if(row==null)break;after=row.n;try(InputStream in=target.getContentResolver().openInputStream(row.source)){java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");byte[] buffer=new byte[65536];int n;long size=0;while((n=in.read(buffer))!=-1){hash.update(buffer,0,n);size+=n;}require(size==row.item.size&&ProtocolCore.equal(hash.digest(),row.item.hash),"actual receiver bytes match durable receipt");total+=size;}}
