  phase="send";runOnMainSync(()->engine.sendUsingExisting(code));long until=SystemClock.elapsedRealtime()+180000;while(SystemClock.elapsedRealtime()<until){if(engine.pendingConfirmation!=null)runOnMainSync(()->engine.decide(true));if(engine.status==R.string.sender_complete)break;if(!engine.isActive())throw new AssertionError("sender ended status="+engine.status);Thread.sleep(100);}require(engine.status==R.string.sender_complete,"sender saved hash acknowledgments");waitFor(()->!engine.isActive(),10000,"sender cleanup");require(engine.receiptProjection.acknowledged()==3,"exactly three verified SAVED projections");result.putLong("selectedCount",engine.selectedCount());result.putLong("fixtureBytes",2162690);assertOriginalFinished(false,3);result.putBoolean("nativeSenderTlsAndAcknowledgments",true);
